def compute(vars):
    compensation_expense_millions = vars["v1"]
    shares_issued = vars["v2"]

    if shares_issued == 0:
        return None

    compensation_expense_dollars = compensation_expense_millions * 1_000_000
    average_share_price = compensation_expense_dollars / shares_issued

    return {
        "value": average_share_price,
        "trace": {
            "compensation_expense_dollars": compensation_expense_dollars,
            "shares_issued": shares_issued,
            "output_meta": {
                "currency": "USD",
                "scale": "ones",
                "unit": "USD/share"
            }
        }
    }
